## Prepare plotting labels ---------------------------------------------------

# Drop rare non-CAF initial clusters when their maximum contribution to any
# niche is less than 1%. The filtered order is used for the supplementary
# non-CAF heatmap and the composition barplot.
initial_labels_to_drop <- niche_label_count_table %>%
  dplyr::filter(stringr::str_detect(.data$label_for_summary, "^Ini-")) %>%
  dplyr::group_by(.data$label_for_summary) %>%
  dplyr::summarise(
    max_prop_within_niche = max(.data$prop_within_niche, na.rm = TRUE),
    .groups = "drop"
  ) %>%
  dplyr::filter(.data$max_prop_within_niche < 0.01) %>%
  dplyr::pull(.data$label_for_summary)

non_caf_label_display_order_for_supplementary <- setdiff(
  initial_label_display_order,
  initial_labels_to_drop
)


label_display_order_for_barplot <- setdiff(
  label_display_order,
  initial_labels_to_drop
)


## Plot niche composition heatmaps -------------------------------------------

make_niche_composition_heatmap <- function(
    plot_table,
    fill_column,
    fill_title,
    fill_breaks,
    viridis_option
) {
  fill_values <- dplyr::pull(plot_table, {{ fill_column }})
  fill_max <- max(fill_values, na.rm = TRUE)
  ggplot(
    plot_table,
    aes(
      x = .data$label_for_summary,
      y = .data$niche,
      fill = {{ fill_column }}
    )
  ) +
    geom_tile(color = "gray25", linewidth = 0.2) +
    scale_x_discrete(
      expand = expansion(mult = c(0, 0)),
      labels = label_names
    ) +
    scale_y_discrete(
      expand = expansion(mult = c(0, 0)),
      labels = niche_annotation,
      position = "right"
    ) +
    scale_fill_viridis_c(
      option = viridis_option,
      trans = "sqrt",
      limits = c(
        0, 
        fill_max
      ),
      breaks = fill_breaks,
      labels = function(x) x * 100,
      guide = guide_colorbar(
        direction = "horizontal",
        title.position = "top",
        title.hjust = 0.5,
        frame.colour = "black",
        ticks.colour = "black"
      )
    ) +
    labs(
      x = NULL,
      y = NULL,
      fill = fill_title
    ) +
    coord_fixed(ratio = 1.10) +
    theme_classic() +
    theme(
      axis.text.x = element_text(
        angle = 45,
        hjust = 1,
        vjust = 1,
        color = "black"
      ),
      axis.text.y = element_text(color = "black"),
      legend.position = "bottom",
      legend.title = element_text(color = "black"),
      legend.text = element_text(color = "black"),
      axis.line = element_blank(),
      panel.border = element_rect(fill = NA, color = "black"),
      plot.background = element_rect(fill = "transparent", color = NA),
      panel.background = element_rect(fill = "transparent", color = NA),
      legend.background = element_rect(fill = "transparent", color = NA)
    )
}


## Supplementary heatmap: non-CAF clusters only ------------------------------

niche_label_count_supplementary_heatmap_table <- niche_label_count_table %>%
  dplyr::filter(.data$label_for_summary %in% non_caf_label_display_order_for_supplementary) %>%
  dplyr::mutate(
    niche = factor(.data$niche, levels = rev(niche_order)),
    label_for_summary = factor(
      .data$label_for_summary,
      levels = non_caf_label_display_order_for_supplementary
    )
  )

# Prepare the three-level x-axis: cluster number, grouping segment, and group
# name. Positions are recalculated after rare clusters are excluded.
supplementary_heatmap_axis_table <- initial_cluster_group_table %>%
  dplyr::filter(.data$label_for_summary %in% non_caf_label_display_order_for_supplementary) %>%
  dplyr::mutate(
    label_for_summary = factor(
      .data$label_for_summary,
      levels = non_caf_label_display_order_for_supplementary
    ),
    x_position = as.numeric(.data$label_for_summary)
  ) %>%
  dplyr::arrange(.data$x_position)

supplementary_heatmap_group_table <- supplementary_heatmap_axis_table %>%
  dplyr::group_by(.data$cell_type_group) %>%
  dplyr::summarise(
    x_min = min(.data$x_position) - 0.32,
    x_max = max(.data$x_position) + 0.32,
    x_mid = mean(range(.data$x_position)),
    .groups = "drop"
  )

supplementary_heatmap_highlight_table <- tibble::tribble(
  ~xmin, ~xmax, ~ymin, ~ymax,
   0.5,   5.5,   9.5,  10.5,
   3.5,   7.5,   8.5,   9.5,
   7.5,  10.5,   7.5,   8.5,
  10.5,  11.5,   6.5,   7.5,
  11.5,  12.5,   5.5,   6.5,
  12.5,  14.5,   4.5,   5.5,
  14.5,  15.5,   3.5,   4.5,
  15.5,  18.5,   2.5,   3.5,
  15.5,  20.5,   1.5,   2.5,
  22.5,  23.5,   0.5,   1.5
)

