  ) +
  theme(
    axis.text.x = element_blank(),
    axis.title.x = element_blank(),
    plot.margin = margin(
      t = 5.5,
      r = 5.5,
      b = 0,
      l = 5.5
    )
  ) +
  geom_rect(
    data = supplementary_heatmap_highlight_table,
    aes(
      xmin = .data$xmin,
      xmax = .data$xmax,
      ymin = .data$ymin,
      ymax = .data$ymax
    ),
    inherit.aes = FALSE,
    fill = NA,
    color = "orange"
  )

supplementary_heatmap_group_axis <- ggplot() +
  geom_text(
    data = supplementary_heatmap_axis_table,
    aes(
      x = .data$x_position,
      y = 3.0,
      label = .data$cluster_number
    ),
    size = 9 / ggplot2::.pt,
    color = "black",
    vjust = 1.2
  ) +
  geom_segment(
    data = supplementary_heatmap_group_table,
    aes(
      x = .data$x_min,
      xend = .data$x_max,
      y = 2.60,
      yend = 2.60
    ),
    linewidth = 0.7,
    lineend = "butt",
    color = "black"
  ) +
  geom_text(
    data = supplementary_heatmap_group_table,
    aes(
      x = .data$x_mid,
      y = 2.4,
      label = .data$cell_type_group
    ),
    angle = 45,
    hjust = 1,
    vjust = 0.65,
    size = 9 / ggplot2::.pt,
    color = "black"
  ) +
  scale_x_continuous(
    limits = c(
      0.5,
      length(non_caf_label_display_order_for_supplementary) + 0.5
    ),
    expand = expansion(mult = c(0, 0))
  ) +
  scale_y_continuous(
    limits = c(0, 3),
    expand = expansion(mult = c(0, 0))
  ) +
  coord_cartesian(clip = "off") +
  theme_void() +
  theme(
    plot.margin = margin(t = 0, r = 5.5, b = 2, l = 5.5),
    plot.background = element_rect(fill = "transparent", color = NA)
  )

cluster_composition_within_niche_heatmap_supplementary_figure <-
