    niche
  ) %>%
  dplyr::inner_join(
    caf_umap_table,
    by = "full_id"
  ) %>%
  dplyr::mutate(
    niche = factor(.data$niche, levels = niche_order)
  )

caf_subcluster_umap_by_niche_plot <- ggplot(
  caf_umap_niche_table,
  aes(x = .data$caf_umap_1, y = .data$caf_umap_2)
) +
  ggrastr::rasterise(
    geom_point(
      aes(color = .data$caf_subcluster),
      size = 0.1
    ),
    dpi = figure_dpi,
    dev = "ragg"
  ) +
  facet_wrap(
    . ~ niche,
    ncol = 4,
    labeller = labeller(niche = niche_annotation)
  ) +
  scale_color_manual(
    values = caf_subcluster_colors_label_named,
    breaks = rev(caf_subcluster_display_order)
  ) +
  guides(
    color = guide_legend(override.aes = list(size = 4))
  ) +
  labs(
    x = "UMAP 1",
    y = "UMAP 2",
    color = NULL
  ) +
  coord_fixed(ratio = 1) +
  theme_classic() +
  theme(
    axis.text = element_blank(),
    axis.ticks = element_blank(),
    axis.line = element_blank(),
    axis.title = element_text(color = "black"),
    legend.text = element_text(color = "black"),
    strip.text = element_text(color = "black"),
    legend.background = element_rect(fill = "transparent", color = NA),
    strip.background = element_rect(fill = "transparent", color = NA),
    plot.background = element_rect(fill = "transparent", color = NA),
    panel.background = element_rect(fill = "transparent", color = NA),
    panel.border = element_rect(fill = NA, color = "black"),
    panel.grid = element_blank()
  )

ggsave(
  plot = caf_subcluster_umap_by_niche_plot,
  filename = file.path(
    niche_figure_dir,
    "spatial_niche_caf_subcluster_umap_by_niche.pdf"
  ),
  width = 11,
  height = 11,
  bg = figure_bg,
  device = grDevices::cairo_pdf
)


## Save point-only CAF UMAP panels for each spatial niche --------------------

# Use the common coordinate range from the faceted plot so that every PNG has
# the same UMAP position and scale as its corresponding facet panel.
caf_umap_x_limits <- range(
  caf_umap_niche_table$caf_umap_1,
  na.rm = TRUE
)

caf_umap_y_limits <- range(
  caf_umap_niche_table$caf_umap_2,
  na.rm = TRUE
)

caf_umap_panel_aspect_ratio <-
  diff(caf_umap_y_limits) / diff(caf_umap_x_limits)

# Approximate physical width of one panel in the 11 x 11 inch faceted PDF.
caf_umap_by_niche_panel_width <- 2.36

for (target_niche in niche_order) {
  target_niche_annotation <- unname(niche_annotation[[target_niche]])

  target_niche_file_label <- target_niche_annotation %>%
    stringr::str_to_lower() %>%
    stringr::str_replace_all("[^a-z0-9]+", "_") %>%
    stringr::str_remove("_$")

  target_niche_plot <- caf_umap_niche_table %>%
    dplyr::filter(as.character(.data$niche) == target_niche) %>%
    ggplot(
      aes(x = .data$caf_umap_1, y = .data$caf_umap_2)
    ) +
    ggrastr::rasterise(
      geom_point(
        aes(color = .data$caf_subcluster),
        size = 0.1
      ),
      dpi = figure_dpi,
      dev = "ragg"
    ) +
    scale_x_continuous(limits = caf_umap_x_limits) +
    scale_y_continuous(limits = caf_umap_y_limits) +
    scale_color_manual(
      values = caf_subcluster_colors_label_named,
      breaks = rev(caf_subcluster_display_order)
    ) +
    coord_fixed(ratio = 1) +
    guides(color = "none") +
    theme_void() +
    theme(
      plot.margin = margin(0, 0, 0, 0, unit = "pt"),
      plot.background = element_rect(fill = "transparent", color = NA),
      panel.background = element_rect(fill = "transparent", color = NA)
    )

  ggsave(
    plot = target_niche_plot,
    filename = file.path(
      niche_figure_dir,
      paste0(
        "spatial_niche_caf_subcluster_umap_",
        target_niche_file_label,
        "_only_points.png"
      )
    ),
    width = caf_umap_by_niche_panel_width,
    height = caf_umap_by_niche_panel_width * caf_umap_panel_aspect_ratio,
    units = "in",
    bg = figure_bg,
    dpi = figure_dpi
  )
}


message(
  "Saved spatial niche analysis figures to: ",
  niche_figure_dir
)
